import React, { useState, useEffect } from 'react';

const API = 'http://localhost:5000/api';

function DepartmentMngt() {
  const [departments, setDepartments] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch(`${API}/departments`)
      .then(r => r.json())
      .then(data => { setDepartments(data); setLoading(false); })
      .catch(() => setLoading(false));
  }, []);

  return (
    <div className="animate-fade-in">
      <div className="content-card">
        <div className="card-header-custom">
          <h5>🏢 Quản Lý Phòng Ban</h5>
          <button className="btn btn-primary-custom btn-sm">+ Thêm Phòng Ban</button>
        </div>
        <div className="table-responsive">
          <table className="table table-custom">
            <thead>
              <tr>
                <th>Mã PB</th>
                <th>Tên Phòng Ban</th>
                <th className="text-center">Thao Tác</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr><td colSpan="3" className="text-center py-4 text-muted">⏳ Đang tải...</td></tr>
              ) : departments.length === 0 ? (
                <tr><td colSpan="3" className="text-center py-4 text-muted">Chưa có dữ liệu</td></tr>
              ) : (
                departments.map(d => (
                  <tr key={d.DepartmentID}>
                    <td><strong>#{d.DepartmentID}</strong></td>
                    <td>{d.DepartmentName}</td>
                    <td className="text-center">
                      <button className="btn btn-sm btn-outline-warning me-1">✏️</button>
                      <button className="btn btn-sm btn-outline-danger">🗑️</button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

export default DepartmentMngt;
